module parity_8bit (
    input [7:0] in,
    output out
);
    wire n1, n2, n3, n4, n5;

    xor(n1, in[0], in[1]);
    xor(n2, in[2], in[3]);
    xor(n3, in[4], in[5]);
    xor(n4, in[6], in[7]);
    xor(n5, n1, n2);
    xor(out, n3, n4, n5);

endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);
    wire nsel0, nsel1;
    wire sel0_and_in0, sel0_and_in1, sel1_and_in2, sel1_and_in3;
    wire or1_output, or2_output;

    not (nsel0, sel[0]);
    not (nsel1, sel[1]);

    and (sel0_and_in0, in[0], nsel1, nsel0);
    and (sel0_and_in1, in[1], nsel1, sel[0]);
    and (sel1_and_in2, in[2], sel[1], nsel0);
    and (sel1_and_in3, in[3], sel[1], sel[0]);

    or (or1_output, sel0_and_in0, sel0_and_in1);
    or (or2_output, sel1_and_in2, sel1_and_in3);
    or (out, or1_output, or2_output);
endmodule

module majority (
    input a, b, c,
    output out
);
    wire ab, bc, ca;

    and u1 (ab, a, b);
    and u2 (bc, b, c);
    and u3 (ca, c, a);
    or u4 (out, ab, bc, ca);
endmodule

module bin_to_gray (
    input [3:0] binary,
    output [3:0] gray
);
    assign gray[3] = binary[3];
    assign gray[2] = binary[3] ^ binary[2];
    assign gray[1] = binary[2] ^ binary[1];
    assign gray[0] = binary[1] ^ binary[0];
endmodule

module eq_comparator (
    input [3:0] a,
    input [3:0] b,
    output equal
);

    wire [3:0] xnor_bits;
    wire all_equal;

    assign xnor_bits[0] = ~(a[0] ^ b[0]);
    assign xnor_bits[1] = ~(a[1] ^ b[1]);
    assign xnor_bits[2] = ~(a[2] ^ b[2]);
    assign xnor_bits[3] = ~(a[3] ^ b[3]);

    assign all_equal = xnor_bits[0] & xnor_bits[1] & xnor_bits[2] & xnor_bits[3];

    assign equal = all_equal;

endmodule

module decoder_2to4 (
    input [1:0] in,
    output [3:0] out
);

    assign out[0] = ~in[1] & ~in[0];
    assign out[1] = ~in[1] &  in[0];
    assign out[2] =  in[1] & ~in[0];
    assign out[3] =  in[1] &  in[0];

endmodule

module priority_encoder (
    input [3:0] in,
    output reg [1:0] code
);
    always @(*) begin
        case (1'b1)
            in[3]: code = 2'b11;
            in[2]: code = 2'b10;
            in[1]: code = 2'b01;
            in[0]: code = 2'b00;
            default: code = 2'b00;
        endcase
    end
endmodule

module fsm_3state (
    input clk, reset,
    output [1:0] state
);
    reg [1:0] q;
    wire d0, d1, q0_not, q1_not;

    assign q0_not = ~q[0];
    assign q1_not = ~q[1];
    assign d0 = (q1_not & q[0]) | (q[1] & q0_not);
    assign d1 = (q1_not & q0_not) | (reset & q[1]) | (~reset & q[1] & q[0]);

    always @(posedge clk or posedge reset) begin
        if (reset) 
            q <= 2'b00;
        else 
            q <= {d1, d0};
    end

    assign state = q;

endmodule

module traffic_light (
    input clk, reset,
    output reg [2:0] light
);

    reg [1:0] state, next_state;

    // State Encoding
    localparam S0 = 2'b00;
    localparam S1 = 2'b01;
    localparam S2 = 2'b10;

    // State Register
    always @(posedge clk or posedge reset) begin
        if (reset)
            state <= S0;
        else
            state <= next_state;
    end

    // Next State Logic
    always @(*) begin
        case (state)
            S0: next_state = S1;
            S1: next_state = S2;
            S2: next_state = S0;
            default: next_state = S0;
        endcase
    end

    // Output Logic
    always @(*) begin
        case (state)
            S0: light = 3'b001; // Green
            S1: light = 3'b010; // Yellow
            S2: light = 3'b100; // Red
            default: light = 3'b000;
        endcase
    end
endmodule

module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output reg [1:0] state
);

    reg q1, q2;  // Flip-flop outputs
    wire d1, d2; // Flip-flop inputs

    // Flip-flop input logic
    assign d1 = (~q1 & ~q2 & up_request) | (~q1 & q2 & ~down_request);
    assign d2 = (~q1 & ~q2 & down_request) | (q1 & ~q2 & ~up_request);

    // State logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            q1 <= 0;
            q2 <= 0;
        end else begin
            q1 <= d1;
            q2 <= d2;
        end
    end

    assign state = {q2, q1};

endmodule

module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);
    reg [1:0] state_reg, state_next;

    // State encoding
    localparam IDLE = 2'b00,
               WAIT = 2'b01,
               DISPENSE = 2'b10;

    always @(posedge clk or posedge reset) begin
        if (reset) 
            state_reg <= IDLE;
        else 
            state_reg <= state_next;
    end

    always @(*) begin
        case (state_reg)
            IDLE: 
                if (coin_inserted)
                    state_next = WAIT;
                else
                    state_next = IDLE;
            WAIT: 
                if (item_selected)
                    state_next = DISPENSE;
                else if (!coin_inserted)
                    state_next = IDLE;
                else
                    state_next = WAIT;
            DISPENSE: 
                state_next = IDLE;
            default: 
                state_next = IDLE;
        endcase
    end

    assign state = state_reg;

endmodule

module power (
    input signed [7:0] in_0,
    input signed [3:0] in_1,
    output signed [15:0] out
);

    assign out = in_0 ** in_1;

endmodule

module log2_int (
    input signed [15:0] in_0,
    output signed [7:0] out
);

    // Wire declarations
    wire [15:0] not_in;
    wire [14:0] intermediate;
    wire [7:0] final_out;

    // NOT gates
    assign not_in = ~in_0;

    // AND gates and intermediate signals (as per circuit diagram)
    assign intermediate[0] = in_0[14] & in_0[13];
    assign intermediate[1] = intermediate[0] & in_0[12];
    assign intermediate[2] = in_0[11] & in_0[10];
    assign intermediate[3] = intermediate[2] & in_0[9];
    assign intermediate[4] = in_0[8] & in_0[7];
    assign intermediate[5] = intermediate[4] & in_0[6];
    assign intermediate[6] = in_0[5] & not_in[4];
    assign intermediate[7] = intermediate[6] & in_0[3];
    assign intermediate[8] = not_in[2] & in_0[1];
    assign intermediate[9] = intermediate[8] & in_0[0];

    // Final outputs (as per circuit diagram)
    assign final_out[0] = intermediate[9];
    assign final_out[1] = intermediate[7];
    assign final_out[2] = intermediate[5];
    assign final_out[3] = in_0[4] & intermediate[3];
    assign final_out[4] = intermediate[1] & in_0[2];
    assign final_out[5] = in_0[3];
    assign final_out[6] = in_0[2];
    assign final_out[7] = in_0[1];

    // Assign final output
    assign out = final_out;

endmodule

module add_8bit (
    input signed [7:0] a, b,
    output signed [8:0] out
);
    wire [7:0] carry;
    wire [7:0] sum;

    // Bit 0
    assign sum[0] = a[0] ^ b[0];
    assign carry[0] = a[0] & b[0];

    // Bit 1
    assign sum[1] = a[1] ^ b[1] ^ carry[0];
    assign carry[1] = (a[1] & b[1]) | (a[1] & carry[0]) | (b[1] & carry[0]);

    // Bit 2
    assign sum[2] = a[2] ^ b[2] ^ carry[1];
    assign carry[2] = (a[2] & b[2]) | (a[2] & carry[1]) | (b[2] & carry[1]);

    // Bit 3
    assign sum[3] = a[3] ^ b[3] ^ carry[2];
    assign carry[3] = (a[3] & b[3]) | (a[3] & carry[2]) | (b[3] & carry[2]);

    // Bit 4
    assign sum[4] = a[4] ^ b[4] ^ carry[3];
    assign carry[4] = (a[4] & b[4]) | (a[4] & carry[3]) | (b[4] & carry[3]);

    // Bit 5
    assign sum[5] = a[5] ^ b[5] ^ carry[4];
    assign carry[5] = (a[5] & b[5]) | (a[5] & carry[4]) | (b[5] & carry[4]);

    // Bit 6
    assign sum[6] = a[6] ^ b[6] ^ carry[5];
    assign carry[6] = (a[6] & b[6]) | (a[6] & carry[5]) | (b[6] & carry[5]);

    // Bit 7
    assign sum[7] = a[7] ^ b[7] ^ carry[6];
    assign carry[7] = (a[7] & b[7]) | (a[7] & carry[6]) | (b[7] & carry[6]);

    // Output
    assign out = {carry[7], sum};

endmodule

module mult_4bit (
    input [3:0] a, b,
    output [7:0] out
);
    wire [3:0] p0, p1, p2, p3;
    wire [6:0] carry;

    // Partial products
    assign p0 = a & {4{b[0]}};
    assign p1 = a & {4{b[1]}};
    assign p2 = a & {4{b[2]}};
    assign p3 = a & {4{b[3]}};

    // Connecting adders
    assign out[0] = p0[0];

    assign {carry[0], out[1]} = p0[1] + p1[0];
    assign {carry[1], out[2]} = p0[2] + p1[1] + carry[0];
    assign {carry[2], out[3]} = p0[3] + p1[2] + p2[0] + carry[1];
    assign {carry[3], out[4]} = p1[3] + p2[1] + p3[0] + carry[2];
    assign {carry[4], out[5]} = p2[2] + p3[1] + carry[3];
    assign {carry[5], out[6]} = p2[3] + p3[2] + carry[4];
    assign {carry[6], out[7]} = p3[3] + carry[5];

endmodule

module subtract_8bit (
    input signed [7:0] a, b,
    output signed [8:0] diff
);
    wire [7:0] b_complement;
    wire [8:0] sum;
    wire carry_out;

    // 2's complement by inverting bits and adding 1
    assign b_complement = ~b + 8'b00000001;

    // Adding 'a' and 'b_complement' to find the difference
    assign {carry_out, sum} = a + b_complement;

    // Output the signed result
    assign diff = sum;
endmodule

module bitwise_ops (
    input [7:0] a, b,
    output [7:0] and_out,
    output [7:0] or_out,
    output [7:0] xor_out
);

assign and_out = a & b;
assign or_out = a | b;
assign xor_out = a ^ b;

endmodule

module left_shift (
    input [7:0] in,
    input [2:0] shift,
    output [7:0] out
);

    wire [7:0] stage1, stage2;

    assign stage1[0] = shift[0] ? 1'b0 : in[0];
    assign stage1[1] = shift[0] ? in[0] : in[1];
    assign stage1[2] = shift[0] ? in[1] : in[2];
    assign stage1[3] = shift[0] ? in[2] : in[3];
    assign stage1[4] = shift[0] ? in[3] : in[4];
    assign stage1[5] = shift[0] ? in[4] : in[5];
    assign stage1[6] = shift[0] ? in[5] : in[6];
    assign stage1[7] = shift[0] ? in[6] : in[7];

    assign stage2[0] = shift[1] ? 1'b0 : stage1[0];
    assign stage2[1] = shift[1] ? 1'b0 : stage1[1];
    assign stage2[2] = shift[1] ? stage1[0] : stage1[2];
    assign stage2[3] = shift[1] ? stage1[1] : stage1[3];
    assign stage2[4] = shift[1] ? stage1[2] : stage1[4];
    assign stage2[5] = shift[1] ? stage1[3] : stage1[5];
    assign stage2[6] = shift[1] ? stage1[4] : stage1[6];
    assign stage2[7] = shift[1] ? stage1[5] : stage1[7];

    assign out[0] = shift[2] ? 1'b0 : stage2[0];
    assign out[1] = shift[2] ? 1'b0 : stage2[1];
    assign out[2] = shift[2] ? 1'b0 : stage2[2];
    assign out[3] = shift[2] ? 1'b0 : stage2[3];
    assign out[4] = shift[2] ? stage2[0] : stage2[4];
    assign out[5] = shift[2] ? stage2[1] : stage2[5];
    assign out[6] = shift[2] ? stage2[2] : stage2[6];
    assign out[7] = shift[2] ? stage2[3] : stage2[7];

endmodule

module bitwise_not (
    input [7:0] in,
    output [7:0] out
);

assign out = ~in;

endmodule

module rotate_left (
    input [7:0] in,
    input [2:0] shift,
    output [7:0] out
);
    wire [7:0] stage1, stage2, stage3;

    // Shift by 1 bit
    assign stage1[0] = shift[0] ? in[1] : in[0];
    assign stage1[1] = shift[0] ? in[2] : in[1];
    assign stage1[2] = shift[0] ? in[3] : in[2];
    assign stage1[3] = shift[0] ? in[4] : in[3];
    assign stage1[4] = shift[0] ? in[5] : in[4];
    assign stage1[5] = shift[0] ? in[6] : in[5];
    assign stage1[6] = shift[0] ? in[7] : in[6];
    assign stage1[7] = shift[0] ? in[0] : in[7];

    // Shift by 2 bits
    assign stage2[0] = shift[1] ? stage1[2] : stage1[0];
    assign stage2[1] = shift[1] ? stage1[3] : stage1[1];
    assign stage2[2] = shift[1] ? stage1[4] : stage1[2];
    assign stage2[3] = shift[1] ? stage1[5] : stage1[3];
    assign stage2[4] = shift[1] ? stage1[6] : stage1[4];
    assign stage2[5] = shift[1] ? stage1[7] : stage1[5];
    assign stage2[6] = shift[1] ? stage1[0] : stage1[6];
    assign stage2[7] = shift[1] ? stage1[1] : stage1[7];

    // Shift by 4 bits
    assign stage3[0] = shift[2] ? stage2[4] : stage2[0];
    assign stage3[1] = shift[2] ? stage2[5] : stage2[1];
    assign stage3[2] = shift[2] ? stage2[6] : stage2[2];
    assign stage3[3] = shift[2] ? stage2[7] : stage2[3];
    assign stage3[4] = shift[2] ? stage2[0] : stage2[4];
    assign stage3[5] = shift[2] ? stage2[1] : stage2[5];
    assign stage3[6] = shift[2] ? stage2[2] : stage2[6];
    assign stage3[7] = shift[2] ? stage2[3] : stage2[7];

    // Final output
    assign out = stage3;

endmodule

module relu (
    input signed [15:0] in_0,
    output signed [15:0] out);

    assign out = (in_0[15] == 1'b1) ? 16'b0 : in_0;

endmodule

module caesar_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);
    assign data_out[0] = ~data_in[7];
    assign data_out[1] = data_in[6] ^ data_in[0];
    assign data_out[2] = data_in[5] ^ data_in[1];
    assign data_out[3] = (data_in[4] ^ data_in[2]) | (~data_in[5]);
    assign data_out[4] = data_in[3] ^ data_in[6];
    assign data_out[5] = data_in[2] & data_in[7];
    assign data_out[6] = data_in[1] | data_in[3];
    assign data_out[7] = data_in[0] ^ data_in[4];
endmodule

module modular_add_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);

assign data_out[0] = ~data_in[0];
assign data_out[1] = data_in[0] ^ data_in[1];
assign data_out[2] = data_in[2] ^ data_in[3];
assign data_out[3] = (data_in[1] & data_in[3]) | (data_in[0] & data_in[3]);
assign data_out[4] = (data_in[4] | data_in[5]);
assign data_out[5] = (data_in[5] & ~data_in[6]) | data_in[4];
assign data_out[6] = (data_in[6] ^ data_in[7]);
assign data_out[7] = (~data_in[7] & (data_in[5] | data_in[6]));

endmodule

module feistel_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);
    parameter KEY = 4'b1010;

    wire [3:0] left, right;
    wire [3:0] subkey_left, subkey_right, xor_result;

    assign left = data_in[7:4];
    assign right = data_in[3:0];

    assign subkey_left = left ^ KEY;
    assign subkey_right = right ^ KEY;

    assign xor_result = subkey_left ^ subkey_right;

    assign data_out[7:4] = subkey_left;
    assign data_out[3:0] = xor_result;

endmodule

module clock_div2 (
    input clk,
    input rst,
    output clk_out
);

    wire q;

    // D Flip-Flop instantiation
    DFF dff_inst (
        .C(clk),
        .D(~q),
        .R(rst),
        .Q(q)
    );

    assign clk_out = q;

endmodule

module DFF (
    input C,
    input D,
    input R,
    output reg Q
);

    always @(posedge C or posedge R) begin
        if (R)
            Q <= 1'b0;
        else
            Q <= D;
    end

endmodule

module comparator_4bit(input [3:0] a, input [3:0] b, output gt, eq, lt);

  wire [3:0] xnor_ab, not_a, not_b, and1, and2, and3;

  // Equality wires
  assign xnor_ab[3] = ~(a[3] ^ b[3]);
  assign xnor_ab[2] = ~(a[2] ^ b[2]);
  assign xnor_ab[1] = ~(a[1] ^ b[1]);
  assign xnor_ab[0] = ~(a[0] ^ b[0]);

  // Greater than wires
  assign not_a[3] = ~a[3];
  assign not_a[2] = ~a[2];
  assign not_a[1] = ~a[1];
  assign not_a[0] = ~a[0];

  assign not_b[3] = ~b[3];
  assign not_b[2] = ~b[2];
  assign not_b[1] = ~b[1];
  assign not_b[0] = ~b[0];

  assign and1[3] = b[3] & not_a[3];
  assign and1[2] = xnor_ab[3] & b[2] & not_a[2];
  assign and1[1] = xnor_ab[3] & xnor_ab[2] & b[1] & not_a[1];
  assign and1[0] = xnor_ab[3] & xnor_ab[2] & xnor_ab[1] & b[0] & not_a[0];

  // Less than wires
  assign and2[3] = a[3] & not_b[3];
  assign and2[2] = xnor_ab[3] & a[2] & not_b[2];
  assign and2[1] = xnor_ab[3] & xnor_ab[2] & a[1] & not_b[1];
  assign and2[0] = xnor_ab[3] & xnor_ab[2] & xnor_ab[1] & a[0] & not_b[0];

  // Combining the signals
  assign lt = and1[3] | and1[2] | and1[1] | and1[0];
  assign gt = and2[3] | and2[2] | and2[1] | and2[0];
  assign eq = xnor_ab[3] & xnor_ab[2] & xnor_ab[1] & xnor_ab[0];

endmodule

module decoder_2to4 (
    input  [1:0] in,
    input        enable,
    output [3:0] out
);

    wire n_in0, n_in1, en_in0, en_in1, en_n_in0, en_n_in1;

    // Generate inverted inputs
    not (n_in0, in[0]);
    not (n_in1, in[1]);

    // Enable signals with inputs and their inverses
    and (en_in0, enable, in[0]);
    and (en_in1, enable, in[1]);
    and (en_n_in0, enable, n_in0);
    and (en_n_in1, enable, n_in1);

    // Generate outputs
    and (out[0], en_n_in1, en_n_in0);
    and (out[1], en_n_in1, en_in0);
    and (out[2], en_in1, en_n_in0);
    and (out[3], en_in1, en_in0);

endmodule

module decoder3to8(input [2:0] in, input enable, output [7:0] out);
  assign out[0] = enable & ~in[2] & ~in[1] & ~in[0];
  assign out[1] = enable & ~in[2] & ~in[1] &  in[0];
  assign out[2] = enable & ~in[2] &  in[1] & ~in[0];
  assign out[3] = enable & ~in[2] &  in[1] &  in[0];
  assign out[4] = enable &  in[2] & ~in[1] & ~in[0];
  assign out[5] = enable &  in[2] & ~in[1] &  in[0];
  assign out[6] = enable &  in[2] &  in[1] & ~in[0];
  assign out[7] = enable &  in[2] &  in[1] &  in[0];
endmodule

module demux_1to2 (
    input  in,
    input  sel,
    output out0,
    output out1
);

    assign out1 = in & sel;
    assign out0 = in & ~sel;

endmodule

module demux_1to4 (
    input        in,
    input  [1:0] sel,
    output       out0,
    output       out1,
    output       out2,
    output       out3
);

    assign out0 = in & ~sel[1] & ~sel[0];
    assign out1 = in & ~sel[1] & sel[0];
    assign out2 = in & sel[1] & ~sel[0];
    assign out3 = in & sel[1] & sel[0];

endmodule

module gray_counter8(
    input wire clk,
    input wire rst,
    output wire [7:0] count
);

    reg [7:0] bin_count;       // Binary counter
    reg [7:0] gray_count;      // Gray code value

    // Binary counter logic
    always @(posedge clk) begin
        if (rst)
            bin_count <= 8'b0;
        else
            bin_count <= bin_count + 1;
    end

    // Convert binary to gray code
    always @(posedge clk) begin
        if (rst)
            gray_count <= 8'b0;
        else
            gray_count <= bin_count ^ (bin_count >> 1);
    end

    assign count = gray_count;

endmodule

module johnson_counter4 (
    input clk,
    input rst,
    output [3:0] q
);

    reg [3:0] shift_reg;

    always @(posedge clk or posedge rst) begin
        if (rst)
            shift_reg <= 4'b0000;
        else
            shift_reg <= {~shift_reg[0], shift_reg[3:1]};
    end

    assign q = shift_reg;

endmodule

module piso_8bit(
    input clk,
    input rst,
