module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);

  wire n0, n1, n2, n3, n4, n5, n6, n7, n8;
  reg q0, q1, q2;

  // Logic for n0 to n8
  assign n0 = ~r[0];
  assign n1 = r[1] & r[2];
  assign n2 = ~r[1];
  assign n3 = n0 & n2;
  assign n4 = r[0] & n1;
  assign n5 = n3 | n4;
  assign n6 = n5 & r[2];
  assign n7 = q0 & ~n6;
  assign n8 = ~q1 & q2;

  // Sequential logic
  always @(posedge clk or negedge resetn) begin
    if (!resetn) begin
      q0 <= 1'b0;
      q1 <= 1'b0;
      q2 <= 1'b0;
    end else begin
      q0 <= n7;
      q1 <= n8;
      q2 <= q0;
    end
  end

  // Output logic
  assign g[0] = q0 & q2;
  assign g[1] = q1 | q2;
  assign g[2] = ~q2;

endmodule

