module TopModule (
  input clk,
  input reset,
  output reg [3:0] q
);

  wire d0, d1, d2, d3;

  // D Flip-Flop logic
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      q <= 4'b0000;
    end else begin
      q[0] <= d0;
      q[1] <= d1;
      q[2] <= d2;
      q[3] <= d3;
    end
  end

  // Logic for D inputs
  assign d0 = ~q[3] & ~q[0];
  assign d1 = q[0] ^ q[3];
  assign d2 = q[1] & ~q[2];
  assign d3 = (q[2] | q[1]) & ~q[3];

endmodule

