  wire d0, d1, d2, d3;
  reg q0, q1, q2, q3;

  assign d0 = ~q3;
  assign d1 = q0 & ~q3;
  assign d2 = q1 ^ q3;
  assign d3 = (q2 & q3) | (~q2 & ~q3);

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      q0 <= 0;
      q1 <= 0;
      q2 <= 0;
      q3 <= 0;
    end else begin
      q0 <= d0;
      q1 <= d1;
      q2 <= d2;
      q3 <= d3;
    end
  end

  always @(*) begin
    q[0] = q0;
    q[1] = q1;
    q[2] = q2;
    q[3] = q3;
  end

endmodule

module TopModule (
  input clk,
  input reset,
  output reg [3:0] q
);

  wire d0, d1, d2, d3;
  wire q0, q1, q2, q3;

  // Flip-flop 0
  assign d0 = (~q0 & ~q1 & ~q2 & ~q3);
  always @(posedge clk or posedge reset) begin
    if (reset)
      q[0] <= 1'b0;
    else
      q[0] <= d0;
  end

  // Flip-flop 1
  assign d1 = (q0 & ~q1 & ~q2 & ~q3);
  always @(posedge clk or posedge reset) begin
    if (reset)
      q[1] <= 1'b0;
    else
      q[1] <= d1;
  end

  // Flip-flop 2
  assign d2 = (q1 & ~q2 & ~q3);
  always @(posedge clk or posedge reset) begin
    if (reset)
      q[2] <= 1'b0;
    else
      q[2] <= d2;
  end

  // Flip-flop 3
  assign d3 = (q2 & ~q3);
  always @(posedge clk or posedge reset) begin
    if (reset)
      q[3] <= 1'b0;
    else
      q[3] <= d3;
  end

endmodule

module TopModule (
  input clk,
  input areset,
  input train_valid,
  input train_taken,
  output logic [1:0] state
);

  logic dff0, dff1;
