  logic and0, and1, and2, and3;
  logic or0, or1;

  assign not_dff0 = ~dff0;
  assign not_dff1 = ~dff1;

  assign and0 = train_valid & train_taken;
  assign and1 = train_valid & not_dff0 & not_dff1;
  assign and2 = not_dff1 & dff0;
  assign and3 = not_dff0 & dff1;

  assign or0 = and0 | and1;
  assign or1 = and2 | and3;

  always_ff @(posedge clk or posedge areset) begin
    if (areset) begin
      dff0 <= 0;
      dff1 <= 0;
    end else begin
      dff0 <= or0;
      dff1 <= or1;
    end
  end

  assign state = {dff1, dff0};

endmodule

