module TopModule (
  input [7:0] a,
  input [7:0] b,
  output [7:0] s,
  output overflow
);
  wire [7:0] carry;
  wire [7:0] p, g;

  // Generate propagate and generate signals
  assign p = a ^ b;
  assign g = a & b;

  // Sum and carry logic for each bit
  assign s[0] = p[0];
  assign carry[0] = g[0];

  assign s[1] = p[1] ^ carry[0];
  assign carry[1] = (p[1] & carry[0]) | g[1];

  assign s[2] = p[2] ^ carry[1];
  assign carry[2] = (p[2] & carry[1]) | g[2];

  assign s[3] = p[3] ^ carry[2];
  assign carry[3] = (p[3] & carry[2]) | g[3];

  assign s[4] = p[4] ^ carry[3];
  assign carry[4] = (p[4] & carry[3]) | g[4];

  assign s[5] = p[5] ^ carry[4];
  assign carry[5] = (p[5] & carry[4]) | g[5];

  assign s[6] = p[6] ^ carry[5];
  assign carry[6] = (p[6] & carry[5]) | g[6];

  assign s[7] = p[7] ^ carry[6];
  assign carry[7] = (p[7] & carry[6]) | g[7];

  // Overflow detection
  assign overflow = carry[7] ^ carry[6];
endmodule

