  wire and1_out, and2_out, and3_out, and4_out;
  wire or1_out, or2_out;

  // Inverters
  assign not_in = ~in;
  assign not_clk = ~clk;
  assign not_reset = ~reset;

  // Flip-Flops
  always @(posedge clk or posedge reset) begin
    if (reset)
      q1 <= 0;
    else
      q1 <= d1;
  end

  always @(posedge clk or posedge reset) begin
    if (reset)
      q2 <= 0;
