  // AND gates
  assign and1_out = not_reset & q1;
  assign and2_out = q2 & q3;
  assign and3_out = not_clk & q2;
  assign and4_out = q1 & not_in;

  // OR gates
  assign or1_out = and1_out | and2_out;
  assign or2_out = and3_out | and4_out;

  // D inputs for flip-flops
  assign d1 = or1_out;
