module TopModule (
  input [3:0] x,
  input [3:0] y,
  output [4:0] sum
);

  wire [4:0] carry;
  wire [3:0] temp_sum;

  // Full adder for bit 0
  assign temp_sum[0] = x[0] ^ y[0];
  assign carry[0] = x[0] & y[0];

  // Full adder for bit 1
  assign temp_sum[1] = x[1] ^ y[1] ^ carry[0];
  assign carry[1] = (x[1] & y[1]) | (carry[0] & (x[1] ^ y[1]));

  // Full adder for bit 2
  assign temp_sum[2] = x[2] ^ y[2] ^ carry[1];
  assign carry[2] = (x[2] & y[2]) | (carry[1] & (x[2] ^ y[2]));

  // Full adder for bit 3
  assign temp_sum[3] = x[3] ^ y[3] ^ carry[2];
  assign carry[3] = (x[3] & y[3]) | (carry[2] & (x[3] ^ y[3]));

  // Final carry out
  assign carry[4] = carry[3];

  // Assign final sum
  assign sum = {carry[4], temp_sum};

endmodule

