module TopModule (
  input clk,
  input reset,
  input w,
  output z
);

  wire q1, q2, q3, d1, d2, d3;
  wire not_w, not_q1, not_q2, and1_out, and2_out, and3_out, or1_out;

  // Inverters
  assign not_w = ~w;
  assign not_q1 = ~q1;
  assign not_q2 = ~q2;

  // AND gates
  assign and1_out = q2 & not_w;
  assign and2_out = q1 & w;
  assign and3_out = not_q2 & q3;

  // OR gate
  assign or1_out = and1_out | and3_out;

  // Flip-flop logic
  assign d1 = and1_out;
  assign d2 = or1_out;
  assign d3 = and2_out;

  // Flip-flops
  always @(posedge clk or posedge reset) begin
    if (reset) begin
      q1 <= 1'b0;
      q2 <= 1'b0;
      q3 <= 1'b0;
    end else begin
      q1 <= d1;
      q2 <= d2;
      q3 <= d3;
    end
  end

  // Output logic
  assign z = q1 & not_q2;

endmodule

