  wire and0, and1, or0, or1;

  // Negations
  assign not_a = ~a;
  assign not_d_ff1 = ~d_ff1;
  assign not_d_ff2 = ~d_ff2;

  // Logic gates
  assign and0 = d_ff0 & not_d_ff1;
  assign and1 = not_d_ff1 & d_ff2;
  assign or0 = and0 | and1 | not_a;
  assign or1 = a | (not_d_ff2 & d_ff1);

  // Sequential logic (D flip-flops)
  always @(posedge clk) begin
    d_ff0 <= or0;
    d_ff1 <= or1;
    d_ff2 <= d_ff0;
