  input c,
  input d,
  output out_sop,
  output out_pos
);
  wire not_a, not_b, not_c, not_d;
  wire and1, and2, and3, and4, or_sop;
  wire or1, or2, or3, and_pos;

  // Negate inputs
  not (not_a, a);
  not (not_b, b);
  not (not_c, c);
  not (not_d, d);

  // For SOP (Sum of Products)
  and (and1, not_a, d);
  and (and2, a, not_b);
  and (and3, c, and1);
  and (and4, and2, not_c);
  or (or_sop, and3, and4);
  not (out_sop, or_sop);

  // For POS (Product of Sums)
  or (or1, a, b);
  or (or2, not_c, d);
  or (or3, c, not_d);
  and (and_pos, or1, or2, or3);
  not (out_pos, and_pos);

endmodule

