module TopModule (
  input in,
  input [1:0] state,
  output reg [1:0] next_state,
  output out
);
  wire not_in, not_state0, not_state1;
  wire and1, and2, and3, and4, and5, and6;
  wire or1, or2;

  // NOT gates
  assign not_in = ~in;
  assign not_state0 = ~state[0];
  assign not_state1 = ~state[1];

  // AND gates
  assign and1 = state[0] & not_state1 & not_in;
  assign and2 = not_state0 & state[1] & in;
  assign and3 = state[0] & state[1] & not_in;
  assign and4 = not_state0 & not_state1 & in;
  assign and5 = not_state0 & not_state1 & not_in;
  assign and6 = state[0] & not_state1 & in;

  // OR gates
  assign or1 = and1 | and2 | and3;
  assign or2 = and4 | and5 | and6;

  // Assign next state
  always @(*) begin
    next_state[0] = or1;
    next_state[1] = or2;
  end

  // Output logic
  assign out = state[0] & state[1];
endmodule

