module TopModule (
  input clk,
  input reset,
  input in,
  output disc,
  output flag,
  output err
);
  reg [2:0] state;
  reg disc_reg, flag_reg, err_reg;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      state <= 3'b000;
      disc_reg <= 1'b0;
      flag_reg <= 1'b0;
      err_reg <= 1'b0;
    end else begin
      case (state)
        3'b000: begin
          if (in) state <= 3'b001;
        end
        3'b001: begin
          if (~in) state <= 3'b010;
          else state <= 3'b011;
        end
        3'b010: begin
          if (in) state <= 3'b001;
          else state <= 3'b100;
        end
        3'b011: begin
          if (~in) state <= 3'b100;
          else err_reg <= 1'b1;
        end
        3'b100: begin
          if (in) flag_reg <= 1'b1;
          else disc_reg <= 1'b1;
        end
        default: state <= 3'b000;
      endcase
    end
  end

  assign disc = disc_reg;
  assign flag = flag_reg;
  assign err = err_reg;
endmodule

module TopModule (
