  assign next_state[1] = (state[4] | ~state[5]) & state[6];
  assign next_state[2] = state[7] ^ (state[8] & ~state[9]);
  assign next_state[3] = (state[0] & state[1]) | (~state[2] & state[3]);
  assign next_state[4] = in & (state[4] | state[5]);
  assign next_state[5] = state[6] | (~state[7] & state[8]);
  assign next_state[6] = (state[9] & ~in) | state[0];
  assign next_state[7] = state[1] ^ state[2];
  assign next_state[8] = (state[3] | state[4]) & ~state[5];
  assign next_state[9] = ~state[6] & (in | state[7]);

  assign out1 = state[8] & state[9];
  assign out2 = ~state[0] | state[1];

endmodule

module TopModule (
  input clk,
  input [7:0] in,
  input reset,
  output done
);

  wire rst_n;
  wire counter_enable;
  wire [2:0] counter_out;
  wire done_signal;

  // Active-low reset generation
  not u1 (rst_n, reset);

  // Counter enable logic
  and u2 (counter_enable, rst_n, clk);

  // 3-bit Counter instantiation
  always @(posedge clk or negedge rst_n)
    if (!rst_n)
      counter_out <= 3'b000;
    else if (counter_enable)
      counter_out <= counter_out + 1;

  // AND gate for done signal
  and u3 (done_signal, counter_out[2], counter_out[1]);

  // D Flip-Flop for synchronization
  reg done_ff;
  always @(posedge clk or negedge rst_n)
    if (!rst_n)
      done_ff <= 0;
    else
      done_ff <= done_signal;

  // Output assignment
  assign done = done_ff;

endmodule

module TopModule (
  input clk,
  input in,
  input reset,
  output done
);

  wire n1, n2, n3, n4, n5, n6, n7, n8;
  wire q1, q2, q3, d1, d2, d3;

  // Inverter
  not u1 (n1, in);

  // AND gates
  and u2 (n2, q1, n1);
  and u3 (n3, q2, in);
  and u4 (n4, q3, n1);
  and u5 (n5, q1, in);
  and u6 (n6, q2, n1);
  and u7 (n7, q3, in);

  // OR gates
  or u8 (n8, n4, n5, n6, n7);

  // D Flip-Flops
  assign d1 = n2;
  assign d2 = n3;
  assign d3 = n8;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      q1 <= 0;
      q2 <= 0;
      q3 <= 0;
    end else begin
      q1 <= d1;
      q2 <= d2;
      q3 <= d3;
    end
  end

  // Output logic
  assign done = q3;

endmodule

