module TopModule (
  input a,
  input b,
  input c,
  output out
);

  wire or1_out;
  wire and1_out;

  assign or1_out = a | b;
  assign and1_out = or1_out & c;

  assign out = and1_out;

endmodule

module TopModule (
  input a,
  input b,
  input c,
  input d,
  output out
);
  wire not_b, not_a, and_1, and_2, and_3, or_1;

  not(not_b, b);
  not(not_a, a);
  and(and_1, not_b, c);
  and(and_2, not_a, d);
  and(and_3, b, c);
  or(or_1, and_1, and_2);
  nor(out, or_1, and_3);

endmodule

module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  output walk_left,
  output walk_right
);
  reg state;

  always @(posedge clk or posedge areset) begin
    if (areset) 
      state <= 1'b0;
    else if (bump_left) 
      state <= 1'b0;
    else if (bump_right) 
      state <= 1'b1;
  end

  assign walk_left = ~state;
  assign walk_right = state;

endmodule

module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  input ground,
  output walk_left,
  output walk_right,
  output aaah
);
  reg state_left;
  reg state_right;

  wire next_left, next_right;
  wire falling;

  // Combinational logic for state transitions
  assign next_left = (state_right & ground & ~bump_left) | (state_left & ground & ~bump_left);
  assign next_right = (state_left & ground & ~bump_right) | (state_right & ground & ~bump_right);
  assign falling = ~ground;

  // D flip-flops for state registers
  always @(posedge clk or posedge areset) begin
    if (areset) begin
      state_left <= 0;
      state_right <= 1; // Start walking right
    end else begin
      state_left <= next_left;
      state_right <= next_right;
    end
  end

  // Outputs
  assign walk_left = state_left & ~falling;
  assign walk_right = state_right & ~falling;
  assign aaah = falling;

endmodule

module TopModule (
  input x,
  input y,
  output z
);

  assign z = ~(x | y);

endmodule

module TopModule (
  input x,
  input y,
  output z
);
  assign z = ~(x | y);
endmodule

module TopModule (
  input clk,
  input reset,
  input data,
  output start_shifting
);
  wire q1, q2, q3;
  wire and1_out, or1_out, and2_out;

  // First D Flip-Flop
  always @(posedge clk or posedge reset) begin
    if (reset)
      q1 <= 1'b0;
    else
      q1 <= data;
  end

  // Second D Flip-Flop
  always @(posedge clk or posedge reset) begin
    if (reset)
      q2 <= 1'b0;
    else
      q2 <= q1;
  end

  // Third D Flip-Flop
  always @(posedge clk or posedge reset) begin
    if (reset)
      q3 <= 1'b0;
    else
      q3 <= q2;
  end

  // AND gate 1
  assign and1_out = q1 & q2;

  // OR gate
  assign or1_out = data | and1_out;

  // AND gate 2
  assign and2_out = or1_out & q3;

  // Final D Flip-Flop with Enable
  reg start_shifting_reg;
  always @(posedge clk or posedge reset) begin
    if (reset)
      start_shifting_reg <= 1'b0;
    else if (and2_out)
      start_shifting_reg <= 1'b1;
  end

  assign start_shifting = start_shifting_reg;

endmodule

module TopModule (
  input clk,
  input reset,
  output shift_ena
);

  wire q1, q2, q3, reset_n;

  assign reset_n = ~reset;

  // First flip-flop with reset
  always @(posedge clk or negedge reset_n) begin
    if (!reset_n)
      q1 <= 1'b0;
    else
      q1 <= ~q1;
  end

  // Second flip-flop with reset
  always @(negedge clk or negedge reset_n) begin
    if (!reset_n)
      q2 <= 1'b0;
    else
      q2 <= q1;
  end

  // Third flip-flop with reset
  always @(posedge clk or negedge reset_n) begin
    if (!reset_n)
      q3 <= 1'b0;
    else
      q3 <= q2;
  end

  // Logic gates to generate shift_ena
  assign shift_ena = q1 & q2 & ~q3;

endmodule

module TopModule (
  input x3,
  input x2,
  input x1,
  output f
);

  assign f = (x1 & x3) | (~x1 & x2);

endmodule

module TopModule (
  input [3:0] x,
  output logic f
);
  logic n1, n2, n3, n4, n5, n6, n7;

  assign n1 = ~(x[1] & x[3]);
  assign n2 = ~(x[3] | x[2]);
  assign n3 = ~(n1 & n2);
  assign n4 = x[0] | x[2];
  assign n5 = n3 ^ n4;
  assign n6 = n4 & n1;
  assign n7 = n5 | n6;
  assign f = ~n7;

endmodule

module TopModule (
  input clk,
  input resetn,
  input x,
  input y,
  output f,
  output g
);

  wire not_resetn, not_x, not_y;
  wire and1, and2, and3, and4, and5, and6, and7;
  wire or1, or2, or3;
  wire dff1_out, dff2_out, dff3_out;

  // NOT gates
  assign not_resetn = ~resetn;
  assign not_x = ~x;
  assign not_y = ~y;

  // AND gates
  assign and1 = x & y;
  assign and2 = not_x & dff1_out;
  assign and3 = dff1_out & dff3_out;
  assign and4 = dff2_out & not_y;
  assign and5 = or1 & not_resetn;
  assign and6 = dff2_out & x;
  assign and7 = or2 & clk;

  // OR gates
  assign or1 = and1 | and2;
  assign or2 = and3 | and4;
  assign or3 = dff3_out | and6;

  // Flip-flops
  always @(posedge clk or negedge resetn) begin
    if (!resetn) begin
      dff1_out <= 0;
      dff2_out <= 0;
      dff3_out <= 0;
    end else begin
      dff1_out <= and5;
      dff2_out <= and7;
      dff3_out <= or3;
    end
  end

  // Outputs
  assign f = ~dff1_out;
  assign g = ~or2;

endmodule

module TopModule (
  input clock,
  input a,
  output reg p,
  output reg q
);

  reg latch_output;

  always @* begin
    if (clock)
      latch_output = a;
  end

  always @* begin
    p = latch_output;
    q = ~latch_output;
  end

endmodule

module TopModule (
  input clk,
  input x,
  output z
);
  wire d1, d2, d3, q1, q2, q3, and1_out, and2_out, or1_out, z_not;

  and (and1_out, x, q1);
  or (or1_out, x, q2);
  and (and2_out, q2, q3);

  // D flip-flops
  always @(posedge clk) begin
    q1 <= and1_out;
    q2 <= or1_out;
    q3 <= and2_out;
  end

  not (z_not, q3);
  assign z = z_not;

endmodule

module TopModule (
  input clk,
  input areset,
  input x,
  output z
);

  reg q1, q2;

  always @(posedge clk or posedge areset) begin
    if (areset) 
      q1 <= 1'b0;
    else 
      q1 <= x;
  end

  always @(posedge clk or posedge areset) begin
    if (areset) 
      q2 <= 1'b0;
    else 
      q2 <= q1;
  end

  assign z = q1 ^ q2;

endmodule

module TopModule (
  input clk,
  input reset,
  output reg [4:0] q
);

  reg [4:0] d;

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      d <= 5'b00000;
    end else begin
      d[0] <= d[4];
      d[1] <= d[0];
      d[2] <= d[1] ^ d[4];
      d[3] <= d[2];
      d[4] <= d[3];
    end
  end

  always @(posedge clk or posedge reset) begin
    if (reset) begin
      q <= 5'b00000;
    end else begin
      q <= d;
    end
  end

endmodule

module TopModule (
  input [3:0] x,
  output logic f
);
  logic and1_out, and2_out, or_out;

  assign and1_out = x[2] & x[0];
  assign and2_out = x[1] & ~x[3];
  assign or_out = and1_out | and2_out;
  assign f = ~or_out;

endmodule

module TopModule (
  input [2:0] y,
  input w,
  output reg Y1
);
  wire not_w, not_y0, not_y1, and1, and2, or1, nand_out;

  not (not_w, w);
  not (not_y0, y[0]);
  not (not_y1, y[1]);

  and (and1, not_y1, not_w);
  and (and2, y[2], not_y0);

  or (or1, and1, and2);
  nand (nand_out, or1, y[1]);

  assign Y1 = nand_out;
endmodule

module TopModule (
  input d,
  input done_counting,
  input ack,
  input [9:0] state, // 10-bit one-hot current state
  output B3_next,
  output S_next,
  output S1_next,
  output Count_next,
  output Wait_next,
  output done,
  output counting,
  output shift_ena
);

  assign counting = state[8] & ~done_counting;
  assign Count_next = state[8] & ~done_counting;
  assign Wait_next = state[8] & done_counting;

  assign done = state[7] & ack;
  assign shift_ena = state[7] & ~ack;

  assign S_next = state[9] & ~state[7];
  assign B3_next = state[5] & ~state[4];
  assign S1_next = state[0] & state[1] & d;

endmodule

module adder_32bit(A, B, S, C32);
    input [32:1] A;
    input [32:1] B;
    output [32:1] S;
    output C32;

    wire C16;

    cla_16bit U1 (
        .A(A[16:1]),
        .B(B[16:1]),
        .Cin(1'b0),
        .S(S[16:1]),
        .Cout(C16)
    );

    cla_16bit U2 (
        .A(A[32:17]),
        .B(B[32:17]),
        .Cin(C16),
        .S(S[32:17]),
        .Cout(C32)
    );

endmodule

module adder_8bit(
    input [7:0] a, b, 
    input cin, 
    output [7:0] sum, 
    output cout);

    wire [7:0] p, g, c;

    // Generate propagate and generate signals
    assign p = a ^ b;
    assign g = a & b;

    // Carry logic
    assign c[0] = cin;
    assign c[1] = g[0] | (p[0] & c[0]);
    assign c[2] = g[1] | (p[1] & c[1]);
    assign c[3] = g[2] | (p[2] & c[2]);
    assign c[4] = g[3] | (p[3] & c[3]);
    assign c[5] = g[4] | (p[4] & c[4]);
    assign c[6] = g[5] | (p[5] & c[5]);
    assign c[7] = g[6] | (p[6] & c[6]);

    // Sum and carry out
    assign sum = p ^ c[7:0];
    assign cout = g[7] | (p[7] & c[7]);

endmodule

module adder_bcd (
    input  [3:0] A,   // First BCD number (0-9)
    input  [3:0] B,   // Second BCD number (0-9)
    input  Cin,       // Input carry
    output [3:0] Sum, // BCD sum (0-9)
    output Cout       // Output carry
);

    wire [3:0] bin_sum;
    wire carry1, carry2, carry3;
    wire correction_needed;
    wire [3:0] corrected_sum;

    // Binary sum of A, B, and Cin
    assign {carry1, bin_sum} = A + B + Cin;

    // Detect if correction is needed
    assign correction_needed = (bin_sum > 4'd9) || carry1;

    // Add correction (6) if needed
    assign {carry2, corrected_sum} = bin_sum + (correction_needed ? 4'd6 : 4'd0);

    // Assign outputs
    assign Sum = corrected_sum;
    assign Cout = carry2;

endmodule

module comparator_3bit (
    input [2:0] A,
    input [2:0] B,
    output A_greater,
    output A_equal,
    output A_less
);

    wire [2:0] A_gt_B, A_eq_B, A_lt_B;

    assign A_gt_B[2] = A[2] & ~B[2];
    assign A_eq_B[2] = ~(A[2] ^ B[2]);
    assign A_lt_B[2] = ~A[2] & B[2];

    assign A_gt_B[1] = A[1] & ~B[1] & A_eq_B[2];
    assign A_eq_B[1] = ~(A[1] ^ B[1]) & A_eq_B[2];
    assign A_lt_B[1] = ~A[1] & B[1] & A_eq_B[2];

    assign A_gt_B[0] = A[0] & ~B[0] & A_eq_B[1];
    assign A_eq_B[0] = ~(A[0] ^ B[0]) & A_eq_B[1];
    assign A_lt_B[0] = ~A[0] & B[0] & A_eq_B[1];

    assign A_greater = A_gt_B[2] | A_gt_B[1] | A_gt_B[0];
    assign A_equal = A_eq_B[2] & A_eq_B[1] & A_eq_B[0];
    assign A_less = A_lt_B[2] | A_lt_B[1] | A_lt_B[0];

endmodule

module comparator_4bit(
    input [3:0] A,   // First 4-bit input operand
    input [3:0] B,   // Second 4-bit input operand
    output A_greater, 
    output A_equal,   
    output A_less     
);
    wire [3:0] A_gt_B, A_eq_B, A_lt_B;

    assign A_gt_B[3] = A[3] & ~B[3];
    assign A_eq_B[3] = ~(A[3] ^ B[3]);
    assign A_lt_B[3] = ~A[3] & B[3];

    assign A_gt_B[2] = A[2] & ~B[2] & A_eq_B[3];
    assign A_eq_B[2] = ~(A[2] ^ B[2]) & A_eq_B[3];
    assign A_lt_B[2] = ~A[2] & B[2] & A_eq_B[3];

    assign A_gt_B[1] = A[1] & ~B[1] & A_eq_B[2];
    assign A_eq_B[1] = ~(A[1] ^ B[1]) & A_eq_B[2];
    assign A_lt_B[1] = ~A[1] & B[1] & A_eq_B[2];

    assign A_gt_B[0] = A[0] & ~B[0] & A_eq_B[1];
    assign A_eq_B[0] = ~(A[0] ^ B[0]) & A_eq_B[1];
    assign A_lt_B[0] = ~A[0] & B[0] & A_eq_B[1];

    assign A_greater = |A_gt_B;
    assign A_equal = A_eq_B[0];
    assign A_less = |A_lt_B;

endmodule

module counter_12 
(
  input rst_n,
  input clk,
  input valid_count,

  output reg [3:0] out
);

  reg [3:0] q;

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n)
      q <= 4'b0000;
    else if (valid_count)
      q <= q + 1;
  end

  assign out = q;

endmodule

module edge_detect(
	input clk,
	input rst_n,
	input a,

	output reg rise,
	output reg down
);

	reg q1, q2;

	// First stage flip-flop
	always @(posedge clk or negedge rst_n) begin
		if (!rst_n)
			q1 <= 1'b0;
		else
			q1 <= a;
	end

	// Second stage flip-flop
	always @(posedge clk or negedge rst_n) begin
		if (!rst_n)
			q2 <= 1'b0;
		else
			q2 <= q1;
	end

	// Rising edge detection
	always @(posedge clk or negedge rst_n) begin
		if (!rst_n)
			rise <= 1'b0;
		else
			rise <= q1 & ~q2;
	end

	// Falling edge detection
	always @(posedge clk or negedge rst_n) begin
		if (!rst_n)
			down <= 1'b0;
		else
			down <= ~q1 & q2;
	end

endmodule

module freq_divbyeven(
    clk,
    rst_n,
    clk_div
);
    input clk;
    input rst_n;
    output clk_div;
    reg clk_div;

    parameter NUM_DIV = 6;

    reg [2:0] counter;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            counter <= 3'b000;
            clk_div <= 1'b0;
        end else begin
            if (counter == (NUM_DIV - 1)) begin
                counter <= 3'b000;
                clk_div <= ~clk_div;
            end else begin
                counter <= counter + 1;
            end
        end
    end

endmodule

module instr_reg (
    input clk,
    input rst,
    input [1:0] fetch,
    input [7:0] data,
    output [2:0] ins,
    output [4:0] ad1,
    output [7:0] ad2
);
    wire fetch_enable;

    // AND Gate for fetch_enable logic
    assign fetch_enable = fetch[1] & ~fetch[0];

    // Flip-flops for ins
    reg [2:0] ins_reg;
    always @(posedge clk or posedge rst) begin
        if (rst)
            ins_reg <= 3'b0;
        else if (fetch_enable)
            ins_reg <= data[7:5];
    end
    assign ins = ins_reg;

    // Flip-flops for ad1
    reg [4:0] ad1_reg;
    always @(posedge clk or posedge rst) begin
        if (rst)
            ad1_reg <= 5'b0;
        else if (fetch_enable)
            ad1_reg <= data[4:0];
    end
    assign ad1 = ad1_reg;

    // Flip-flops for ad2
    reg [7:0] ad2_reg;
    always @(posedge clk or posedge rst) begin
        if (rst)
            ad2_reg <= 8'b0;
        else if (fetch_enable)
            ad2_reg <= data;
    end
    assign ad2 = ad2_reg;

endmodule

module LFSR (out, clk, rst);
  input clk, rst;
  output reg [3:0] out;

  always @(posedge clk or posedge rst) begin
    if (rst)
      out <= 4'b0000;
    else begin
      out[0] <= out[3] ^ out[2];
      out[1] <= out[0];
      out[2] <= out[1];
      out[3] <= out[2];
    end
  end
endmodule

module right_shifter(clk, q, d);  

    input clk;  
    input d;  
    output reg [7:0] q;  

    always @(posedge clk) begin
        q <= {d, q[7:1]};
    end

endmodule

module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input				brstn   ,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

    reg [3:0] stage1_reg;
    reg [3:0] stage2_reg;
    reg enable_sync;

    always @(posedge clk_a or negedge arstn) begin
        if (!arstn)
            enable_sync <= 0;
        else
            enable_sync <= data_en; 
    end

    always @(posedge clk_a or negedge arstn) begin
        if (!arstn)
            stage1_reg <= 4'b0;
        else if (enable_sync)
            stage1_reg <= data_in;
    end

    always @(posedge clk_b or negedge brstn) begin
        if (!brstn)
            stage2_reg <= 4'b0;
        else
            stage2_reg <= stage1_reg;
    end

    always @(posedge clk_b or negedge brstn) begin
        if (!brstn)
            dataout <= 4'b0;
        else
            dataout <= stage2_reg;
    end

endmodule

module fsm(IN, MATCH, CLK, RST);
    input IN, CLK, RST;
    output reg MATCH;

    reg state0, state1, state2, state3;

    always @(posedge CLK or posedge RST) begin
        if (RST) begin
            state0 <= 0;
            state1 <= 0;
            state2 <= 0;
            state3 <= 0;
            MATCH <= 0;
        end else begin
            state0 <= (IN & ~state0 & ~state1 & ~state2 & ~state3) | (~IN & state3);
            state1 <= (IN & state0);
            state2 <= (IN & state1);
            state3 <= (IN & state2);
            MATCH <= (~IN & state3);
        end
    end
endmodule

module parallel2serial(
    input clk,
    input rst_n,
    input [3:0] d,
    output valid_out,
    output dout
);

    reg [3:0] shift_register;
    reg [2:0] counter;
    reg serial_out, valid_flag;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shift_register <= 4'b0;
            counter <= 3'b0;
            serial_out <= 1'b0;
            valid_flag <= 1'b0;
        end else begin
            if (counter == 3'b000) begin
                shift_register <= d;
                valid_flag <= 1'b1;
            end else begin
                shift_register <= {shift_register[2:0], 1'b0};
                valid_flag <= 1'b0;
            end

            serial_out <= shift_register[3];

            if (counter == 3'b100)
                counter <= 3'b000;
            else
                counter <= counter + 1'b1;
        end
    end

    assign valid_out = valid_flag;
    assign dout = serial_out;

endmodule

module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );

    // Internal signals
    wire q1, q2, q3;
    wire and1_out, and2_out, and3_out, or1_out, inv_out;

    // Flip-flops
    DFF dff1 (.C(clk), .R(~rst_n), .D(data_in & ~q1), .Q(q1));
    DFF dff2 (.C(clk), .R(~rst_n), .D(q1 & ~q2), .Q(q2));
    DFF dff3 (.C(clk), .R(~rst_n), .D((q2 & data_in) | q3), .Q(q3));

    // Logic gates
    assign inv_out = ~data_in;
    assign and1_out = q1 & inv_out;
    assign and2_out = q2 & data_in;
    assign and3_out = q1 & q2 & q3;
    assign or1_out = and1_out | and2_out;

    // Output
    assign sequence_detected = and3_out;

endmodule

module DFF (
    input C, R, D,
    output reg Q
);
    always @(posedge C or negedge R) begin
        if (!R)
            Q <= 0;
        else
            Q <= D;
    end
endmodule
